<?php $this->layout('default'); use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; $rows = H::categories(); $edit = null; foreach ($rows as $r) { if ((string) $r['id'] === V::queryString('editar')) { $edit = $r; } } ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/ticket-category-save"><header class="cms-card-head"><div><h2><?= $edit ? 'Editar categoria' : 'Cadastrar categoria' ?></h2><small>Disponível ao cliente quando ativa.</small></div><?= V::icon('list') ?></header><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><input type="hidden" name="back" value="/chamados/categorias"><?= V::field('Nome', 'name', $edit['name'] ?? '', ['required' => true]) ?><?= V::field('Ordem', 'sort_order', $edit['sort_order'] ?? '0', ['type' => 'number']) ?><?= V::field('Ativa', 'is_active', $edit['is_active'] ?? '1', ['type' => 'checkbox']) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar categoria</button></div></form>
<section class="cms-card"><header class="cms-card-head"><div><h2>Categorias cadastradas</h2></div><b class="cms-count"><?= count($rows) ?></b></header><?php foreach ($rows as $c): ?><div class="cms-row"><div><strong><?= V::e($c['name']) ?></strong> <?= $c['is_active'] ? V::badge('active', 'Ativa') : V::badge('draft', 'Inativa') ?><br><small><?= (int) $c['tickets_count'] ?> chamado(s)</small></div><?= V::iconLink('?editar=' . (int) $c['id'], 'Editar') ?></div><?php endforeach; ?></section></div>
